WITH filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), order_date) AS days_since_order_date, CASE WHEN shipping_fee >= 44 THEN 'High' WHEN shipping_fee >= 11 THEN 'Medium' ELSE 'Low' END AS shipping_fee_band FROM orders WHERE channel IS NOT DISTINCT FROM 'mobile'), metrics AS (SELECT *, LAG(days_since_order_date) OVER (PARTITION BY store_id, channel ORDER BY days_since_order_date, id) AS prev_days_since_order_date, LAG(discount) OVER (PARTITION BY store_id, channel ORDER BY days_since_order_date, id) AS prev_discount, LEAD(discount) OVER (PARTITION BY store_id, channel ORDER BY days_since_order_date, id) AS next_discount, ROW_NUMBER() OVER (PARTITION BY store_id, channel ORDER BY days_since_order_date, id) AS seq_no, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY days_since_order_date NULLS LAST) AS days_since_order_date_dense_rank FROM filtered), kept_keys AS (SELECT id FROM metrics INTERSECT ALL SELECT id FROM orders WHERE customer_id IN (28, 35, 39)), verified AS (SELECT s.* FROM metrics s JOIN kept_keys k ON s.id = k.id), matched AS (SELECT s.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM verified s LEFT JOIN promotions pr ON COALESCE(s.channel, 'web') = pr.channel AND s.order_date >= pr.starts_on AND s.order_date < pr.ends_on + INTERVAL 7 DAYS) SELECT customer_id, measure, val FROM (SELECT customer_id, next_discount, amount, discount_pct, prev_discount FROM matched) src UNPIVOT INCLUDE NULLS (val FOR measure IN (next_discount, amount, discount_pct, prev_discount));
